     1	import { cookies, headers } from 'next/headers';
     2	
     3	function getPreferredLanguage(acceptLanguage: string | null): string {
     4	  if (!acceptLanguage) {
     5	    return 'unknown';
     6	  }
     7	
     8	  const firstLanguage = acceptLanguage.split(',')[0]?.trim();
     9	  if (!firstLanguage) {
    10	    return 'unknown';
    11	  }
    12	
    13	  return firstLanguage.split(';')[0]?.trim() || 'unknown';
    14	}
    15	
    16	export default async function UserPreferences() {
    17	  const cookieStore = await cookies();
    18	  const headerStore = await headers();
    19	
    20	  const theme = cookieStore.get('theme')?.value || 'light';
    21	  const preferredLanguage = getPreferredLanguage(
    22	    headerStore.get('accept-language')
    23	  );
    24	
    25	  return (
    26	    <section>
    27	      <p>
    28	        <strong>Theme:</strong> {theme}
    29	      </p>
    30	      <p>
    31	        <strong>Preferred language:</strong> {preferredLanguage}
    32	      </p>
    33	    </section>
    34	  );
    35	}
